const crypto = require('crypto');
const secret = $env.LENDLOOP_HMAC_SECRET;
if (!secret) {
  throw new Error('LENDLOOP_HMAC_SECRET environment variable is not configured.');
}

const timestamp = String(Math.floor(Date.now() / 1000));
const canonicalTarget = 'GET:/api/automation/overdue-loans';
const signature = 'v1=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${canonicalTarget}`)
  .digest('hex');

return [
  {
    json: {
      timestamp,
      signature,
      todayUtc: new Date().toISOString().slice(0, 10),
    },
  },
];

const response = $input.first().json || {};
const todayUtc = response.todayUtc || new Date().toISOString().slice(0, 10);
const loans = Array.isArray(response.loans) ? response.loans : [];

// Return empty array when there are zero overdue loans so downstream stops cleanly
return loans.map((loan) => ({
  json: {
    loanId: String(loan.loanId),
    toolName: String(loan.toolName),
    endDate: String(loan.endDate),
    daysOverdue: Number(loan.daysOverdue || 1),
    borrowerDisplayName: String(loan.borrowerDisplayName || 'Neighbor'),
    lenderDisplayName: String(loan.lenderDisplayName || 'Neighbor'),
    idempotencyKey: `overdue:${loan.loanId}:${todayUtc}`,
    todayUtc,
  },
}));

const crypto = require('crypto');
const secret = $env.LENDLOOP_HMAC_SECRET;
if (!secret) {
  throw new Error('LENDLOOP_HMAC_SECRET environment variable is not configured.');
}

const loans = $('Expand Overdue Loans & Build Idempotency Keys').all();
const results = [];

for (const item of loans) {
  const loan = item.json;
  const bodyObj = {
    loanId: loan.loanId,
    idempotencyKey: loan.idempotencyKey,
    channel: 'n8n_overdue_workflow',
    messageSummary: `Reminder sent (${loan.daysOverdue}d overdue)`,
  };
  const rawBody = JSON.stringify(bodyObj);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'v1=' + crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${rawBody}`)
    .digest('hex');

  results.push({
    json: {
      rawBody,
      timestamp,
      signature,
      idempotencyKey: loan.idempotencyKey,
    },
  });
}

return results;
